const items = $input.all();
return items.map(item => {
  const payload = item.json.body || item.json;
  const answers = payload.form_response?.answers || [];
  const definition = payload.form_response?.definition || {};
  let score = 0;
  const fields = {};
  answers.forEach((answer, idx) => {
    const fieldTitle = definition.fields?.[idx]?.title || `field_${idx}`;
    const value = answer.text || answer.email || answer.number || answer.choice?.label || answer.boolean || '';
    fields[fieldTitle] = value;
    if (typeof answer.number === 'number') score += answer.number;
  });
  return {
    json: {
      formId: payload.form_response?.form_id || '',
      respondentEmail: answers.find(a => a.email)?.email || '',
      respondentName: answers.find(a => a.text)?.text || '',
      submittedAt: payload.form_response?.submitted_at || new Date().toISOString(),
      score: score,
      answers: JSON.stringify(fields),
      ...fields
    }
  };
});

